const target = { name: 'Ada', role: 'engineer' };

const handler = {
  get(obj, prop) {
    console.log('leyendo', prop);
    return Reflect.get(obj, prop);
  },
  set(obj, prop, value) {
    if (prop === 'role' && typeof value !== 'string') {
      throw new TypeError('role debe ser string');
    }
    return Reflect.set(obj, prop, value);
  },
};

const user = new Proxy(target, handler);
console.log(user.name);
user.role = 'lead';
console.log(target.role);

try {
  user.role = 42;
} catch (err) {
  console.log(err.message);
}
